// Ports sections of the AI voice agents landing-page design file onto /ai-voice-agents.
//
//   node scripts/port-landing-v4.mjs "<path to ai-voice-agents-v4-landing-page.html>"
//
// Writes two generated files (do not edit them by hand, rerun this instead):
//   lib/content/ai-voice-agents-landing-v4.ts   markup of the kept sections + its icon sprite
//   app/ai-voice-agents/landing-v4.css          the design's own CSS, scoped to .v4l
//
// Kept: hero, benefits, features, use cases, cities, how it works. Left out on the client's
// instruction (14 Oct 2026): compare, hear it first, pricing/plans, free live demo, FAQ, and the
// design's stand-in header, footer, offer bar and pop-up forms (their endpoints are dummies).
import { readFileSync, writeFileSync } from "node:fs";
import postcss from "postcss";

const src = readFileSync(process.argv[2], "utf8");
const KEEP = [/<section id="top" class="hero4"/, /aria-labelledby="benefits-title"/, /aria-labelledby="features-title"/,
  /id="use-cases"/, /id="cities"/, /<section id="how"/];

// ---------------------------------------------------------------- markup
const sections = [...src.matchAll(/<section\b[^>]*>[\s\S]*?<\/section>/g)].map((m) => m[0]);
const kept = KEEP.map((re) => {
  const s = sections.find((x) => re.test(x.slice(0, 200)));
  if (!s) throw new Error("section not found: " + re);
  return s;
});

const classTokens = (html, fn) =>
  html.replace(/class="([^"]*)"/g, (_, c) => `class="${fn(c.split(/\s+/).filter(Boolean)).join(" ")}"`);

// Brand width and type rules (site/docs/design-rules.md): one container-omh, no rem/ch caps on
// headings, paragraphs or content grids, 18px descriptions.
const DROP = new Set(["max-w-[56rem]", "max-w-[40rem]", "max-w-[68rem]", "max-w-[72rem]", "text-[clamp(18px,17px+0.3vw,21px)]"]);

let html = kept.join("\n\n");
html = classTokens(html, (t) => t.map((x) => (x === "wrap" ? "container-omh" : x)).filter((x) => !DROP.has(x)));
html = html
  .replace('id="industries"', 'id="industries-strip"') // the page already has a #industries section
  // "Hear it first" is left out; the booking tabs (BookDemo, #book-demo-form) hold "Ring our demo agent now".
  .replaceAll('href="#hear-it"', 'href="#book-demo-form"')
  // The design's pop-up forms are dummies, so its buttons go to the page's working booking tabs.
  .replace(/<button type="button" class="([^"]*)" data-open="(?:callback|demo)"(?: aria-label="[^"]*")?>([\s\S]*?)<\/button>/g,
    '<a href="#book-demo-form" class="$1">$2</a>')
  .replace(/href="#i-/g, 'href="#v4-i-'); // own sprite ids, so the page's existing icons are untouched
const left = html.match(/.{0,80}(?:data-open=|max-w-\[\d+(?:rem|ch)\]|class="(?:[^"]* )?wrap[ "]).{0,40}/g);
if (left) throw new Error("unconverted markup left:\n" + left.join("\n"));

const sprite = src.match(/<svg width="0" height="0"[\s\S]*?<\/svg>/)[0].replace(/<symbol id="i-/g, '<symbol id="v4-i-');

writeFileSync("lib/content/ai-voice-agents-landing-v4.ts",
  "// Generated by scripts/port-landing-v4.mjs from ai-voice-agents-v4-landing-page.html. Do not edit by hand.\n" +
  "// Rendered above the existing page body by app/ai-voice-agents/page.tsx; styles in landing-v4.css (.v4l).\n" +
  "export const landingV4Markup = String.raw`\n" + sprite + "\n\n" + html + "\n`;\n");

// ------------------------------------------------------------------- css
const css = src.match(/<style>\s*([\s\S]*?)<\/style>/)[1];
const SCOPE = ".v4l";
const KEYFRAMES = new Set([...css.matchAll(/@keyframes\s+([\w-]+)/g)].map((m) => m[1]));
const ROOT = /^(?::root|:host|html|body)/;

// The design switches themes only on the root (:root[data-theme=dark], :root.dark, :root:not(...)),
// which the site sets the same way, so those stay as ancestors of the scope.
function scope(sel) {
  sel = sel.trim();
  const m = sel.match(/^((?::root|:host|html|body)[^\s>+~]*)(.*)$/);
  if (!m) return `${SCOPE} ${sel}`;
  const [, head, rest] = m;
  const base = /^(?::root|:host|html|body)$/.test(head) ? SCOPE : `${head.replace(ROOT, ":root")} ${SCOPE}`;
  return rest.trim() ? `${base} ${rest.trim()}` : base;
}

const root = postcss.parse(css);
root.walkAtRules("layer", (at) => {
  at.params = at.params.split(",").map((n) => "v4-" + n.trim()).join(", ");
});
root.walkAtRules("keyframes", (at) => { at.params = "v4-" + at.params; });
root.walkRules((rule) => {
  if (rule.parent.type === "atrule" && /keyframes$/.test(rule.parent.name)) return;
  rule.selectors = rule.selectors.map(scope);
});
root.walkDecls((d) => {
  if (/^animation(-name)?$/.test(d.prop))
    d.value = d.value.replace(/[\w-]+/g, (w) => (KEYFRAMES.has(w) ? "v4-" + w : w));
  // The site self-hosts both fonts through next/font, under generated family names.
  d.value = d.value
    .replace(/"Instrument Sans"/g, 'var(--font-instrument),"Instrument Sans"')
    .replace(/"Source Sans 3"/g, 'var(--font-source-sans),"Source Sans 3"');
});

// Brand overrides, last so they win: full-width centred headers with the site's 30ch title cap,
// 18px descriptions, and the site header's height for the sticky use-case cards.
const BRAND = `
@layer v4-brand {
  ${SCOPE} { --header-h: 85px; /* the site header, sticky, at every width */ }
  /* The design's reset (.v4l * { padding: 0; margin: 0 }) sits in a later layer than the site's
     utilities, so the brand container is restated here. Keep in step with globals.css. */
  ${SCOPE} .container-omh { width: 100%; max-width: 1440px; margin-inline: auto; padding-inline: clamp(20px, 8.4px + 3.09vw, 48px); }
  ${SCOPE} .head-c, ${SCOPE} .head-c .lead, ${SCOPE} .lead { max-width: none; }
  ${SCOPE} .head-c h2, ${SCOPE} .hero4 h1 { margin-inline: auto; }
  ${SCOPE} .lead { font-size: 18px; }
}`;

writeFileSync("app/ai-voice-agents/landing-v4.css",
  "/* Generated by scripts/port-landing-v4.mjs from ai-voice-agents-v4-landing-page.html. Do not edit by hand.\n" +
  "   The design's compiled CSS, scoped to .v4l, its layers renamed v4-* so they never merge with the site's. */\n" +
  root.toString() + "\n" + BRAND + "\n");

console.log(`ok: ${kept.length} sections, ${html.length} chars markup, keyframes ${[...KEYFRAMES].join(" ")}`);
